#pragma once

// The finding codes `document.validate`, `document.patch` and `project.validate` return (ADR-2157,
// Engine API stage S4). One table, so a client can branch on every code: it is published in
// docs/api/errors.md beside the error codes (`api::errorCatalogue`, regenerated by tools/gen_api.sh),
// and a finding is built from a `FindingCode`, never from a string, so no code can be emitted that the
// table does not list. tests/unit/test_api_catalogue.cpp (E2) holds the table to the enum.
//
// A finding is `{severity, code, pointer, message}` (plus `document`: which document `pointer` points
// into). A document with any `error` finding is not valid; `warning` and `info` findings do not change
// that. The severity is the code's, fixed here, so the same fact is never an error in one tool and a
// warning in another.

#include <array>
#include <cstddef>
#include <cstdint>
#include <string_view>

namespace avgen::api {

enum class FindingSeverity : std::uint8_t { Error, Warning, Info };

[[nodiscard]] constexpr std::string_view findingSeverityName(FindingSeverity s) {
    switch (s) {
    case FindingSeverity::Error: return "error";
    case FindingSeverity::Warning: return "warning";
    case FindingSeverity::Info: return "info";
    }
    return "error";
}

enum class FindingCode : std::uint8_t {
    SchemaType,
    SchemaRequired,
    SchemaEnum,
    SchemaRange,
    SchemaInvalid,
    SceneUnknownKey,
    SceneParse,
    SceneMissing,
    ProjectParse,
    ProjectUnknownKey,
    ProjectWarning,
    AssetMissing,
    AssetRelinked,
    ParameterUnknown,
    RouteDead,
    RouteHazard,
};

struct FindingCodeInfo {
    FindingCode id;
    std::string_view code;
    FindingSeverity severity;
    std::string_view meaning;
};

inline constexpr std::array<FindingCodeInfo, 16> kFindingCodes = {{
    {FindingCode::SchemaType, "schema.type", FindingSeverity::Error,
     "A value has the wrong JSON type for its key in the generated document schema (a string where a number "
     "belongs, an array of the wrong length is schema.invalid). `pointer` names the value."},
    {FindingCode::SchemaRequired, "schema.required", FindingSeverity::Error,
     "An object lacks a key its schema requires (`format`, `version`, a node's `kind`, a light's `name`). "
     "`pointer` names the object."},
    {FindingCode::SchemaEnum, "schema.enum", FindingSeverity::Error,
     "A value is not one of the names the engine reads there (a node kind, a light type, a route op); the "
     "message lists them."},
    {FindingCode::SchemaRange, "schema.range", FindingSeverity::Error,
     "A number is outside the range the schema publishes for its key."},
    {FindingCode::SchemaInvalid, "schema.invalid", FindingSeverity::Error,
     "Any other schema violation: a wrong constant (`format`, `version`), an array of the wrong length, a "
     "value matching none of a key's allowed forms. The message is the validator's."},
    {FindingCode::SceneUnknownKey, "scene.unknownKey", FindingSeverity::Warning,
     "A scene key the engine does not read. A file on disk is only warned about (ADR-278); `document.patch` "
     "refuses a patch that adds one with INVALID_ARGUMENTS and this pointer. `_` keys are notes and exempt."},
    {FindingCode::SceneParse, "scene.parse", FindingSeverity::Error,
     "The engine refused the scene document when it built a composition from it, on a private engine; the "
     "message is the parser's."},
    {FindingCode::SceneMissing, "scene.missing", FindingSeverity::Error,
     "The project names a scene that did not load, so the orb stands in for its world (requireProjectScene)."},
    {FindingCode::ProjectParse, "project.parse", FindingSeverity::Error,
     "The engine refused the project document (Engine::loadProject failed); the message is the loader's."},
    {FindingCode::ProjectUnknownKey, "project.unknownKey", FindingSeverity::Info,
     "A top-level project key this build does not read. It is kept verbatim on save (ADR-2132), so this is "
     "not a fault, but it is where a misspelt key shows up."},
    {FindingCode::ProjectWarning, "project.warning", FindingSeverity::Warning,
     "A load warning with no more specific code (Engine::projectWarnings); the message is the engine's."},
    {FindingCode::AssetMissing, "asset.missing", FindingSeverity::Error,
     "A file the document names does not resolve: it does not exist where it resolves, or (for a project's scene, "
     "audio, environment, audio clip, stem or shader layer) it exists and its loader refused it. A node whose asset "
     "is missing is skipped at load and kept on save (ADR-2151); a project reference that did not resolve is kept "
     "as written by every save (ADR-2164, Engine::unresolvedReferences)."},
    {FindingCode::AssetRelinked, "asset.relinked", FindingSeverity::Warning,
     "A file the project names was missing and was found elsewhere under the project folder by name, size and "
     "content hash; the load used that one. Saving the project writes the new path."},
    {FindingCode::ParameterUnknown, "parameter.unknown", FindingSeverity::Warning,
     "A path in the project's `parameters` that no registered parameter answers. It is not applied, and it is "
     "kept verbatim for the next save (ADR-2132)."},
    {FindingCode::RouteDead, "route.dead", FindingSeverity::Warning,
     "The route audit (ADR-902) found a route, track or effect that cannot reach the picture: an unknown source "
     "or target, a target that refuses modulation, a node that emits nothing. The message is the rule's."},
    {FindingCode::RouteHazard, "route.hazard", FindingSeverity::Info,
     "The route audit found an entry that reaches the picture but may not do what it says (a hazard rule)."},
}};

[[nodiscard]] constexpr const FindingCodeInfo& findingCode(FindingCode id) {
    return kFindingCodes[static_cast<std::size_t>(id)];
}

// The table is indexed by the enum: each entry sits at its own value.
[[nodiscard]] constexpr bool findingCodesInOrder() {
    for (std::size_t i = 0; i < kFindingCodes.size(); ++i) {
        if (static_cast<std::size_t>(kFindingCodes[i].id) != i) {
            return false;
        }
    }
    return true;
}
static_assert(findingCodesInOrder(), "kFindingCodes must list FindingCode in declaration order");
static_assert(kFindingCodes.size() == static_cast<std::size_t>(FindingCode::RouteHazard) + 1,
              "every FindingCode needs a kFindingCodes entry");

} // namespace avgen::api
